args.command:
python3 -c "
import csv
themes = {}
with open('inputs/eurostat/indicator_descriptions.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        t = row['theme']
        if t not in themes:
            themes[t] = []
        themes[t].append(row['indicator_id'])
for t, ids in themes.items():
    print(f'{t}: {len(ids)} indicators')
    for i in ids[:5]:
        print(f'  {i}')
    if len(ids) > 5:
        print(f'  ... and {len(ids)-5} more')
"

